// HasStructures applies the HasEdge predicate on the "structures" edge.
func HasStructures() predicate.Property {
	return predicate.Property(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, StructuresTable, StructuresColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasStructuresWith applies the HasEdge predicate on the "structures" edge with a given conditions (other predicates).
func HasStructuresWith(preds ...predicate.Structure) predicate.Property {
	return predicate.Property(func(s *sql.Selector) {
		step := newStructuresStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

